1	//! Read-only source planning for an explicit owner copy. No destination writes.
2	use super::*;
3	use crate::{
4	    evidence_copy_plan::{Plan, Source, Target},
5	    evidence_service as service,
6	};
7	pub(super) const SOURCE_DOMAIN: &[u8] = b"tools.kan.archive.copy-source.v1\0";
8	
9	/// A verified complete legacy snapshot retained by a read-only transaction.
10	/// A plan decoded from disk cannot construct this value without re-verification.
11	pub struct PlannedCopy {
12	    reader: RecoveryReader,
13	    plan: Plan,
14	}
15	pub(super) fn frame(hash: &mut Sha256, bytes: &[u8]) {
16	    hash.update((bytes.len() as u64).to_be_bytes());
17	    hash.update(bytes);
18	}
19	impl PlannedCopy {
20	    /// Pin and fully verify a healthy legacy archive before producing a recipe.
21	    /// The source's derived indexes must also be valid; use the separate recovery
22	    /// workflow first if they need rebuilding. No files are promoted or erased.
23	    pub fn open(
24	        path: &Path,
25	        target: Target,
26	        historical_issuer: String,
27	        nonce: [u8; 32],
28	    ) -> Result<Self> {
29	        // Validate owner configuration before opening source media.
30	        Plan::new(
31	            Source {
32	                through: 0,
33	                tip: None,
34	                digest: [0; 32],
35	                historical_issuer: historical_issuer.clone(),
36	            },
37	            target.clone(),
38	            nonce,
39	        )?;
40	        let reader = RecoveryReader::open(path)?;
41	        reader.ledger.check_write_profile(false)?;
42	        let verification = reader.ledger.verify_contents()?;
43	        let snapshot = &verification.snapshot;
44	        let mut hash = Sha256::new();
45	        hash.update(SOURCE_DOMAIN);
46	        frame(&mut hash, b"commits");
47	        hash.update(snapshot.through.to_be_bytes());
48	        for sequence in 1..=snapshot.through {
49	            let record = reader.record(sequence)?;
50	            let es: Vec<_> = entries(&record.manifest).collect();
51	            if es.len() != 1 {
52	                return Err(Error::Invalid(
53	                    "copy requires a service request per manifest",
54	                ));
55	            }
56	            let object: Cid = cid(&es[0]["ciphertext"])
57	                .parse()
58	                .map_err(|_| Error::Invalid("copy request CID"))?;
59	            // The full audit above has already checked every object size/hash
60	            // in this same pinned transaction. Indexed reads cannot now reveal
61	            // an unaudited oversized row; avoid a full object scan per request.
62	            let request_bytes = reader.ledger.read_object(&object)?;
63	            let signed = service::verify_retained_request(&record, &request_bytes)
64	                .map_err(|_| Error::Corrupt("copy retained request".into()))?;
65	            if signed.request.scope != service::hex(&target.scope)
66	                || signed.request.audience != historical_issuer
67	            {
68	                return Err(Error::Invalid(
69	                    "copy source scope or historical issuer mismatch",
70	                ));
71	            }
72	            hash.update(sequence.to_be_bytes());
73	            frame(&mut hash, record.manifest.bytes());
74	            frame(&mut hash, record.receipt.bytes());
75	            frame(&mut hash, &object.to_bytes());
76	        }
77	        // Bind staged-but-uncommitted objects as well as the committed stream.
78	        // verify_contents already checked every object's CID against its bytes.
79	        frame(&mut hash, b"objects");
80	        hash.update(verification.objects.to_be_bytes());
81	        {
82	            let mut query = reader
83	                .ledger
84	                .conn
85	                .prepare("SELECT cid,length(bytes) FROM objects ORDER BY cid")?;
86	            let mut rows = query.query([])?;
87	            while let Some(row) = rows.next()? {
88	                let id: String = row.get(0)?;
89	                let object: Cid = id.parse().map_err(|_| Error::Invalid("copy object CID"))?;
90	                let length: i64 = row.get(1)?;
91	                frame(&mut hash, &object.to_bytes());
92	                hash.update(
93	                    u64::try_from(length)
94	                        .map_err(|_| Error::Invalid("copy object length"))?
95	                        .to_be_bytes(),
96	                );
97	            }
98	        }
99	        let plan = Plan::new(
100	            Source {
101	                through: snapshot.through,
102	                tip: snapshot.tip.clone(),
103	                digest: hash.finalize().into(),
104	                historical_issuer,
105	            },
106	            target,
107	            nonce,
108	        )?;
109	        Ok(Self { reader, plan })
110	    }
111	    /// Reopen a source and require the entire exact owner-pinned recipe. Matching
112	    /// only the high-water sequence or tip is insufficient for copy resumption.
113	    pub fn confirm(path: &Path, plan: &Plan, expected_archive: &[u8; 32]) -> Result<Self> {
114	        plan.check_archive(expected_archive)?;
115	        let checked = Self::open(
116	            path,
117	            plan.target().clone(),
118	            plan.source().historical_issuer.clone(),
119	            *plan.nonce(),
120	        )?;
121	        if checked.plan.bytes() != plan.bytes() {
122	            return Err(Error::Conflict("copy source differs from pinned plan"));
123	        }
124	        Ok(checked)
125	    }
126	    pub(super) fn reader(&self) -> &RecoveryReader {
127	        &self.reader
128	    }
129	    pub fn plan(&self) -> &Plan {
130	        &self.plan
131	    }
132	    pub fn snapshot(&self) -> Result<Snapshot> {
133	        self.reader.snapshot()
134	    }
135	}
136	
137	/// Retain a recipe before creating its destination. The new file is private and
138	/// durable; errors leave any output for explicit owner inspection.
139	pub fn retain_plan(path: &Path, source: &PlannedCopy) -> Result<()> {
140	    plan_outside_sqlite(&source.reader.source, path)?;
141	    let plan = source.plan();
142	    // surface-write: evidence-copy-plan:artifact
143	    crate::persistence::write_new_owner_only(
144	        crate::persistence::SurfaceWrite::EvidenceCopyPlan,
145	        path,
146	        plan.bytes(),
147	    )?;
148	    std::fs::File::open(parent_directory(path))?.sync_all()?;
149	    let actual = read_plan(path, &plan.archive_id())?;
150	    if actual.bytes() != plan.bytes() {
151	        return Err(Error::Conflict("retained recipe changed"));
152	    }
153	    Ok(())
154	}
155	// A plan is an ordinary retained file, never a SQLite main file or sidecar.
156	fn plan_outside_sqlite(database: &Path, plan: &Path) -> Result<()> {
157	    if same_existing_file(database, plan) {
158	        return Err(Error::Invalid("plan aliases a SQLite database"));
159	    }
160	    sqlite_destination(database, plan)?;
161	    Ok(())
162	}
163	
164	/// Validate plan custody against both SQLite families before any database opens.
165	/// An absent destination root must have an existing parent, as creation requires.
166	/// This protects owner-selected paths under the same trusted-filesystem contract
167	/// as archive creation; it does not fence concurrent hostile path replacement.
168	pub fn read_plan_for_copy(
169	    path: &Path,
170	    source: &Path,
171	    destination_root: &Path,
172	    expected_archive: &[u8; 32],
173	) -> Result<Plan> {
174	    let source = std::fs::canonicalize(source)?;
175	    plan_outside_sqlite(&source, path)?;
176	    let root = if destination_root.exists() {
